#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <errno.h>

static long safe_abs(long v)
{
    if (v == LLONG_MIN) {
        puts("OVERFLOW");
        exit(EXIT_FAILURE);
    }
    return v < 0 ? -v : v;
}

static long gcd_long(long a, long b)
{
    while (b != 0) {
        long r = a % b;
        a = b;
        b = r;
    }
    return a;
}

int main(int argc, char *argv[])
{
    long a, b;
    long abs_a, abs_b;
    long g, l;

    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    {
        char *endptr = NULL;
        errno = 0;
        a = strtol(argv[1], &endptr, 10);
        if (endptr == argv[1] || *endptr != '\0') {
            puts("BAD_INPUT");
            return 0;
        }
    }

    {
        char *endptr = NULL;
        errno = 0;
        b = strtol(argv[2], &endptr, 10);
        if (endptr == argv[2] || *endptr != '\0') {
            puts("BAD_INPUT");
            return 0;
        }
    }

    abs_a = safe_abs(a);
    abs_b = safe_abs(b);

    if (abs_a > 1000000L || abs_b > 1000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    if (abs_a == 0 && abs_b == 0) {
        puts("gcd=0 lcm=0");
        return 0;
    }

    g = gcd_long(abs_a, abs_b);
    l = (abs_a / g) * abs_b;

    printf("gcd=%ld lcm=%ld\n", g, l);
    return 0;
}
